#!/usr/bin/env node
// HERMES structured knowledge -> Nodal Center staging sync.
// Dry-run is default. Live vault writes require BOTH --apply and
// HERMES_NODAL_SYNC_LIVE=true. Inputs are structured canonical candidates
// generated by structure-automotive-knowledge-corpus.mjs. This script never
// reads raw external source text and never promotes knowledge to public/canonical.

import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const {
  targetPathForKnowledgeObject,
  validateNodalCandidate,
  renderNodalCandidate
} = require('../../lib/knowledge-governance/nodal-structured-knowledge');

const root = process.cwd();
const applyRequested = process.argv.includes('--apply');
const live = applyRequested && String(process.env.HERMES_NODAL_SYNC_LIVE || 'false').toLowerCase() === 'true';
if (applyRequested && !live) {
  console.error('[HERMES Nodal sync] --apply requires HERMES_NODAL_SYNC_LIVE=true. Running dry-run.');
}

const inputRoot = path.resolve(live ? 'hermes/structured-knowledge' : 'hermes/structured-knowledge-previews');
const ldDir = path.join(inputRoot, 'ld-automotive', 'canonical-drafts');
const sharedDir = path.join(inputRoot, 'shared-engineering', 'canonical-drafts');
const vaultRoot = path.resolve('elimfilters-vault');
const reportDir = path.resolve('hermes/nodal-sync-reports');
const auditDir = path.join(vaultRoot, '94-sync-log');

function readJsonFiles(dir) {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir)
    .filter((name) => name.endsWith('.json'))
    .sort()
    .map((name) => {
      const fullPath = path.join(dir, name);
      return { file: fullPath, object: JSON.parse(fs.readFileSync(fullPath, 'utf8')) };
    });
}

function ensureInputs() {
  const ld = readJsonFiles(ldDir);
  const shared = readJsonFiles(sharedDir);
  if (!ld.length && !shared.length) {
    throw new Error(`No structured knowledge input found under ${inputRoot}. Run npm run hermes:ld:structure first.`);
  }
  return [...ld, ...shared];
}

const inputs = ensureInputs();
const plans = [];
const errors = [];
for (const item of inputs) {
  const validation = validateNodalCandidate(item.object);
  if (!validation.valid) {
    errors.push({ knowledge_object_id: item.object?.knowledge_object_id || path.basename(item.file), errors: validation.errors });
    continue;
  }
  const relativeTarget = targetPathForKnowledgeObject(item.object);
  const target = path.join(vaultRoot, ...relativeTarget.split('/'));
  const content = renderNodalCandidate(item.object);
  const exists = fs.existsSync(target);
  const decision = exists && fs.readFileSync(target, 'utf8') === content ? 'NOOP' : (exists ? 'UPDATE' : 'CREATE');
  plans.push({
    knowledge_object_id: item.object.knowledge_object_id,
    domain: item.object.domain,
    target: path.relative(root, target).replaceAll('\\', '/'),
    decision,
    content
  });
}

fs.mkdirSync(reportDir, { recursive: true });
const now = new Date().toISOString();
const stamp = now.replace(/[:.]/g, '-');
const summary = plans.reduce((acc, p) => {
  acc[p.decision.toLowerCase()] = (acc[p.decision.toLowerCase()] || 0) + 1;
  return acc;
}, { create: 0, update: 0, noop: 0 });
const report = {
  generated_at: now,
  mode: live ? 'LIVE' : 'DRY_RUN',
  input_root: path.relative(root, inputRoot).replaceAll('\\', '/'),
  objects_read: inputs.length,
  validation_errors: errors,
  summary,
  plans: plans.map(({ content, ...plan }) => plan),
  public_use_allowed: false,
  canonical_promotion: false,
  database_write: false,
  pgvector_write: false,
  catalog_write: false,
  cross_reference_write: false
};
const reportPath = path.join(reportDir, `nodal-structured-sync-${stamp}.json`);
fs.writeFileSync(reportPath, JSON.stringify(report, null, 2) + '\n', 'utf8');
console.log(`[HERMES Nodal sync] mode=${report.mode} objects=${inputs.length} create=${summary.create} update=${summary.update} noop=${summary.noop} invalid=${errors.length}`);
console.log(`[HERMES Nodal sync] report=${path.relative(root, reportPath).replaceAll('\\', '/')}`);

if (errors.length) {
  console.error('[HERMES Nodal sync] BLOCKED — one or more structured objects failed candidate validation.');
  process.exit(1);
}
if (!live) {
  console.log('[HERMES Nodal sync] DRY RUN — no Nodal Center notes were written.');
  process.exit(0);
}

const writable = plans.filter((p) => p.decision === 'CREATE' || p.decision === 'UPDATE');
const backups = [];
const written = [];
try {
  for (const plan of writable) {
    const target = path.resolve(plan.target);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    if (plan.decision === 'UPDATE') {
      const original = fs.readFileSync(target, 'utf8');
      backups.push({ target, original });
      fs.writeFileSync(target, plan.content, 'utf8');
    } else {
      fs.writeFileSync(target, plan.content, { encoding: 'utf8', flag: 'wx' });
    }
    written.push({ target, decision: plan.decision, knowledge_object_id: plan.knowledge_object_id });
  }
} catch (error) {
  for (const item of written.reverse()) {
    const backup = backups.find((b) => b.target === item.target);
    if (backup) fs.writeFileSync(item.target, backup.original, 'utf8');
    else fs.rmSync(item.target, { force: true });
  }
  console.error(`[HERMES Nodal sync] WRITE FAILED — rolled back ${written.length} writes: ${error.message}`);
  process.exit(1);
}

fs.mkdirSync(auditDir, { recursive: true });
const auditPath = path.join(auditDir, `structured-knowledge-sync-${stamp}.json`);
fs.writeFileSync(auditPath, JSON.stringify({
  generated_at: now,
  actor: 'HERMES_STRUCTURED_KNOWLEDGE_SYNC',
  mode: 'LIVE',
  written: written.map((item) => ({
    knowledge_object_id: item.knowledge_object_id,
    decision: item.decision,
    path: path.relative(root, item.target).replaceAll('\\', '/')
  })),
  publication_status: 'candidate_only',
  public_use_allowed: false,
  database_write: false,
  pgvector_write: false,
  catalog_write: false,
  cross_reference_write: false
}, null, 2) + '\n', 'utf8');

console.log(`[HERMES Nodal sync] LIVE — wrote ${written.length} candidate note(s)`);
console.log(`[HERMES Nodal sync] audit=${path.relative(root, auditPath).replaceAll('\\', '/')}`);
